CREATE FUNCTION public.hyrox_can_record(_program_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.hyrox_programs p JOIN public.entitlements e ON e.user_id=p.user_id WHERE p.id=_program_id AND p.user_id=auth.uid() AND p.status='published' AND CASE WHEN e.override_level IS NOT NULL AND e.override_expires_at>now() THEN e.override_level ELSE e.access_level END='full') $$;
REVOKE ALL ON FUNCTION public.hyrox_can_record(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.hyrox_can_record(uuid) TO authenticated,service_role;
ALTER POLICY hyrox_activities_insert ON public.hyrox_activities WITH CHECK(public.hyrox_can_record(program_id));
ALTER POLICY hyrox_activities_update ON public.hyrox_activities USING(public.hyrox_can_record(program_id)) WITH CHECK(public.hyrox_can_record(program_id));
ALTER POLICY hyrox_reviews_insert ON public.hyrox_reviews WITH CHECK(public.hyrox_can_record(program_id));
ALTER POLICY hyrox_reviews_update ON public.hyrox_reviews USING(public.hyrox_can_record(program_id)) WITH CHECK(public.hyrox_can_record(program_id));
ALTER POLICY hyrox_documents_insert ON public.hyrox_documents WITH CHECK(public.has_role(auth.uid(),'admin') OR (category='review_photo' AND public.hyrox_can_record(program_id) AND EXISTS(SELECT 1 FROM public.hyrox_programs p WHERE p.id=program_id AND p.user_id=auth.uid() AND p.status='published') AND storage_path LIKE 'hyrox/'||auth.uid()::text||'/%'));
ALTER POLICY hyrox_student_photo_upload ON storage.objects WITH CHECK(bucket_id='client-documents' AND (storage.foldername(name))[1]='hyrox' AND (storage.foldername(name))[2]=auth.uid()::text AND EXISTS(SELECT 1 FROM public.hyrox_programs p WHERE p.user_id=auth.uid() AND p.status='published' AND public.hyrox_can_record(p.id)));
CREATE FUNCTION public.hyrox_date_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.hyrox_programs p WHERE p.id=NEW.program_id AND NEW.planned_date BETWEEN p.start_date AND p.start_date+89) THEN RAISE EXCEPTION 'Planned date must be within 90 days'; END IF; RETURN NEW; END $$;
CREATE TRIGGER hyrox_date_guard BEFORE INSERT OR UPDATE ON public.hyrox_activities FOR EACH ROW EXECUTE FUNCTION public.hyrox_date_guard();
CREATE FUNCTION public.hyrox_review_snapshot_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF OLD.reviewed_at IS NOT NULL AND NEW.responses IS DISTINCT FROM OLD.responses THEN RAISE EXCEPTION 'Reviewed responses are preserved'; END IF; RETURN NEW; END $$;
CREATE TRIGGER hyrox_review_snapshot_guard BEFORE UPDATE ON public.hyrox_reviews FOR EACH ROW EXECUTE FUNCTION public.hyrox_review_snapshot_guard();